@Composable
fun RouteVisualizer(
    route: Route,
    modifier: Modifier = Modifier
) {
    val widths: MutableList<Float> = mutableListOf()

    for (i in 0 ..< route.partialRoutes.size) {
        val partialRouteTime = route.partialRoutes[i].duration.toFloat()
        widths.add(partialRouteTime / route.duration)

        route.partialRoutes.getOrNull(i + 1)?.let {
            val connectionTime = it.startTime - route.partialRoutes[i].endTime
            widths.add(connectionTime.inWholeMinutes.toFloat() / route.duration)
        }
    }

    Row(
        modifier = modifier
    ) {
        route.partialRoutes.forEachIndexed { index, partialRoute ->
            Canvas(
                modifier = Modifier
                    .height(60.dp)
            ) {

            }
        }

    }
}


fun DrawScope.drawMotLine(
    width: Float,
    height: Float = 0f,
    color: Color
) {
    drawCircle(
        color = color,
        radius = 2f,
        center = Offset(0f, height / 2)
    )
    drawLine(
        color = color,
        start = Offset(0f, height / 2),
        end = Offset(width, height / 2),
        strokeWidth = 1f
    )
    drawCircle(
        color = color,
        radius = 2f,
        center = Offset(width, height / 2)
    )
}

fun DrawScope.drawConnectionArrow(
    width: Float,
    height: Float,
    color: Color
) {
    drawPath(
        path = PathParser.createPathFromPathData("M 0 0 C 0.327 0.341 0.684 0.357 1 0 L 1 0.1 L 1 0 L 0.9 0").asComposePath(),
        color = color,
    )
}


